import{_ as d,o as r,c as a,a0 as e}from"./chunks/framework.ZoVXsKRZ.js";const b=JSON.parse('{"title":"广东麻将「鸡平胡」完全指南","description":"","frontmatter":{"lastUpdated":true},"headers":[],"relativePath":"skills/guangdong.md","filePath":"skills/guangdong.md","lastUpdated":1784794489000}'),l={name:"skills/guangdong.md"};function o(n,t,s,i,h,g){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="广东麻将「鸡平胡」完全指南" tabindex="-1">广东麻将「鸡平胡」完全指南 <a class="header-anchor" href="#广东麻将「鸡平胡」完全指南" aria-label="Permalink to &quot;广东麻将「鸡平胡」完全指南&quot;">​</a></h1><p>广东麻将是华南地区最流行的麻将玩法，也是大多数麻将 App 的默认规则。节奏快、门槛低、老少皆宜。</p><h2 id="基本参数" tabindex="-1">基本参数 <a class="header-anchor" href="#基本参数" aria-label="Permalink to &quot;基本参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><strong>人数</strong></td><td>4 人</td></tr><tr><td><strong>牌数</strong></td><td>136 张（万、筒、条 + 东、南、西、北、中、发、白）</td></tr><tr><td><strong>打法</strong></td><td>鸡平胡 — 吃、碰、杠全开放</td></tr><tr><td><strong>特色</strong></td><td>最低 0 番也能胡，门槛极低</td></tr><tr><td><strong>结算</strong></td><td>自摸三家付；点炮包三家</td></tr></tbody></table><hr><h2 id="核心规则" tabindex="-1">核心规则 <a class="header-anchor" href="#核心规则" aria-label="Permalink to &quot;核心规则&quot;">​</a></h2><h3 id="_1-鸡胡与平胡" tabindex="-1">1. 鸡胡与平胡 <a class="header-anchor" href="#_1-鸡胡与平胡" aria-label="Permalink to &quot;1. 鸡胡与平胡&quot;">​</a></h3><p>广麻最核心的概念：</p><ul><li><strong>鸡胡</strong>：只要有 4 组面子 + 1 对将牌就能胡，没有番数限制。<strong>0 番也能胡。</strong></li><li><strong>平胡</strong>：全部由顺子组成（没有碰/刻），且将牌不能是字牌。1 番起。</li></ul><h3 id="_2-吃碰杠全开放" tabindex="-1">2. 吃碰杠全开放 <a class="header-anchor" href="#_2-吃碰杠全开放" aria-label="Permalink to &quot;2. 吃碰杠全开放&quot;">​</a></h3><p>广麻是所有操作全开放的玩法：</p><ul><li>✅ <strong>可以吃</strong> — 上家打的牌能和手牌凑顺子，喊&quot;吃&quot;</li><li>✅ <strong>可以碰</strong> — 任何人打的牌能和手牌凑刻子，喊&quot;碰&quot;</li><li>✅ <strong>可以杠</strong> — 明杠、暗杠、补杠都行</li></ul><div class="tip custom-block"><p class="custom-block-title">吃碰优先级</p><p>碰 &gt; 吃。如果同时有人要碰和要吃的同一张牌，碰的人优先。</p></div><h3 id="_3-自摸与点炮" tabindex="-1">3. 自摸与点炮 <a class="header-anchor" href="#_3-自摸与点炮" aria-label="Permalink to &quot;3. 自摸与点炮&quot;">​</a></h3><p>广麻结算方式很直接：</p><table tabindex="0"><thead><tr><th>胡牌方式</th><th>谁付钱</th></tr></thead><tbody><tr><td><strong>自摸</strong></td><td>三家各付 1 倍</td></tr><tr><td><strong>点炮</strong></td><td>点炮者一人包赔三家（付 3 倍）</td></tr></tbody></table><hr><h2 id="番型速查表" tabindex="-1">番型速查表 <a class="header-anchor" href="#番型速查表" aria-label="Permalink to &quot;番型速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番型</th><th>说明</th><th style="text-align:center;">番数</th><th>示例</th></tr></thead><tbody><tr><td>鸡胡</td><td>基本胡，0 番也能胡</td><td style="text-align:center;">0</td><td>任意基本牌型</td></tr><tr><td>平胡</td><td>全顺子 + 非字牌将</td><td style="text-align:center;">1</td><td>🀇🀈🀉 🀙🀚🀛 🀐🀑🀒 🀁🀂🀃 🀝🀝</td></tr><tr><td>碰碰胡</td><td>全刻子（全碰）</td><td style="text-align:center;">2</td><td>🀀🀀🀀 🀁🀁🀁 🀂🀂🀂 🀃🀃🀃 🀝🀝</td></tr><tr><td>混一色</td><td>一种花色 + 字牌</td><td style="text-align:center;">3</td><td>全筒子 + 任意字牌</td></tr><tr><td>清一色</td><td>全部同一花色</td><td style="text-align:center;">4</td><td>全部万子 / 全部筒子 / 全部条子</td></tr><tr><td>七小对</td><td>7 个对子</td><td style="text-align:center;">4</td><td>14 张牌全部成对</td></tr><tr><td>混幺九</td><td>全幺九 + 字牌</td><td style="text-align:center;">5</td><td>只有 1、9 和字牌的刻子</td></tr><tr><td>小三元</td><td>中发白有两组刻子 + 一对</td><td style="text-align:center;">5</td><td>中中中 + 发发发 + 白白</td></tr><tr><td>大三元</td><td>中发白各一组刻子</td><td style="text-align:center;">极罕</td><td>中中中 + 发发发 + 白白白</td></tr><tr><td>十三幺</td><td>十三种幺九牌各一张 + 任意一对</td><td style="text-align:center;">极罕</td><td>国士无双</td></tr></tbody></table><hr><h2 id="与四川麻将的-5-大区别" tabindex="-1">与四川麻将的 5 大区别 <a class="header-anchor" href="#与四川麻将的-5-大区别" aria-label="Permalink to &quot;与四川麻将的 5 大区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比维度</th><th>广东麻将</th><th>四川麻将</th></tr></thead><tbody><tr><td>牌数</td><td>136 张（有字牌）</td><td>108 张（无字牌）</td></tr><tr><td>吃牌</td><td>✅ 能吃</td><td>❌ 不能吃</td></tr><tr><td>缺门要求</td><td>无要求</td><td>必须缺一门</td></tr><tr><td>胡牌门槛</td><td>0 番就能胡</td><td>缺一门 + 成牌</td></tr><tr><td>多人胡牌</td><td>只有一人胡</td><td>血战到底，多人胡</td></tr><tr><td>结算</td><td>自摸三家付 / 点炮包三家</td><td>按番数计算</td></tr></tbody></table><hr><h2 id="新手策略" tabindex="-1">新手策略 <a class="header-anchor" href="#新手策略" aria-label="Permalink to &quot;新手策略&quot;">​</a></h2><h3 id="开局阶段" tabindex="-1">开局阶段 <a class="header-anchor" href="#开局阶段" aria-label="Permalink to &quot;开局阶段&quot;">​</a></h3><ol><li><strong>先看手牌番型潜力</strong> — 如果起手花色均匀，走平胡路线；如果某种花色很多，可以冲混一色/清一色</li><li><strong>字牌处理</strong> — 不成对的字牌优先打掉，除非想做混一色/字牌番型</li><li><strong>幺九牌</strong> — 1 和 9 的牌比较难凑顺子，不用的优先弃</li></ol><h3 id="中期博弈" tabindex="-1">中期博弈 <a class="header-anchor" href="#中期博弈" aria-label="Permalink to &quot;中期博弈&quot;">​</a></h3><ol><li><strong>观察对手吃碰</strong> — 对手频繁碰字牌 → 可能在做混一色</li><li><strong>注意花色偏好</strong> — 对手一直不出某花色 → 可能在憋清一色</li><li><strong>安全牌意识</strong> — 别人碰过的牌附近是安全区</li></ol><h3 id="听牌阶段" tabindex="-1">听牌阶段 <a class="header-anchor" href="#听牌阶段" aria-label="Permalink to &quot;听牌阶段&quot;">​</a></h3><ol><li><strong>多面听优先</strong> — 等一张 vs 等三张，概率差三倍</li><li><strong>生张小心</strong> — 好久没人打的牌，很可能别人也在等</li><li><strong>别贪大</strong> — 已经听牌了就别想着改做更大的，错过胡牌更亏</li></ol><hr><p><em>广州、深圳、佛山等地规则细节可能略有不同，打之前确认！</em></p>',32)])])}const u=d(l,[["render",o]]);export{b as __pageData,u as default};
